use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let mut pairs: Vec<(i64, i64)> = input.as_array().unwrap()
        .iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    pairs.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));

    json!(pairs)
}
